/*
 * network/sau2/get_chksum.s - NETWORK_$GET_CHKSUM (m68k / SAU2)
 *
 * Transcribed instruction for instruction from the image at 0x00E11EF0
 * (20 bytes), the first routine of the hand-written NETWORK_ASM segment
 * (SAU2 map: I E11EF0 NETWORK_ASM size = B8, followed by OS_$DATA_COPY and
 * OS_$DATA_ZERO).  No link/unlk; the argument is read at (0x4,SP).
 * Generated by: Claude Opus 5.5
 *
 *   00e11ef0  20 6f 00 04    movea.l (0x4,SP),A0
 *   00e11ef4  70 00          moveq   #0x0,D0
 *   00e11ef6  32 3c 00 ff    move.w  #0xff,D1w
 *   00e11efa  e3 98          rol.l   #0x1,D0
 *   00e11efc  d0 98          add.l   (A0)+,D0
 *   00e11efe  51 c9 ff fa    dbf     D1w,0x00e11efa
 *   00e11f02  4e 75          rts
 *
 * 256 iterations over the page's 256 longwords: the running sum is rotated
 * left one bit before each longword is added (carries out of bit 31 are
 * lost).  The only caller is the NETWORK module's page checksum routine
 * (0x00E0F34A).
 */

        .section ".text.NETWORK_$GET_CHKSUM","ax",@progbits
        .even

        .set    NETWORK_CHKSUM_LOOP_COUNT, 0xFF

/*
 * uint32_t NETWORK_$GET_CHKSUM(uint32_t va)
 *
 * In:  (0x4,SP) = address of a 1024-byte page
 * Out: D0.l     = rotate-and-add checksum of its 256 longwords
 * Clobbers: D0, D1, A0
 */
        .global NETWORK_$GET_CHKSUM
NETWORK_$GET_CHKSUM:
        movea.l (0x4,%sp), %a0                  /* 00e11ef0 */
        moveq   #0, %d0                         /* 00e11ef4 */
        move.w  #NETWORK_CHKSUM_LOOP_COUNT, %d1 /* 00e11ef6 */
.Lloop:
        rol.l   #1, %d0                         /* 00e11efa */
        add.l   (%a0)+, %d0                     /* 00e11efc */
        dbf     %d1, .Lloop                     /* 00e11efe */
        rts                                     /* 00e11f02 */

        .end
